import { Gate, addToGates } from "bareguard";
const gates = ["searcher", "booker"].map((agent) => new Gate({
  audit: { path: null },
  rwx: { agent, agents: { searcher: "r--", booker: "rw-" }, tools: {} },
  humanChannel: async () => ({ decision: "deny" }),
}));
await Promise.all(gates.map((g) => g.init()));
const results = await addToGates(gates, { search: "r" });
results.every((r) => r.ok); // true — both gates now admit "search"

import { createRubric, checkStep } from "bareguard";
const rubric = createRubric({ schema: 1, goal: "g", checkpoints: { resume: { gating: true,
  checks: [{ id: "words-cap", rule: "maxWords", field: "text", value: 600 }] } } });
const r = await checkStep(rubric, "resume", "word ".repeat(633));
// r.verdict === "red"; r.gaps[0] -> { key: "resume:words-cap", measured: 633, limit: 600, direction: "at-most", ... }

import { createRubric, rubricSha } from "bareguard";
const spec = { schema: 1, goal: "Write the resume", checkpoints: { resume: { gating: true,
  checks: [{ id: "words-cap", rule: "maxWords", field: "text", value: 600 }] } } };
const rubric = createRubric(spec, { sha256: rubricSha(spec) }); // throws on a bad spec or a wrong sha

import { Gate } from "bareguard";
const gate = new Gate({
  tools:  { allowlist: ["bash", "read"] },
  bash:   { allow: ["git", "ls"] },
  budget: { maxCostUsd: 5.00 },
  humanChannel: async (event) => ({ decision: "allow" }),
});
await gate.init();
const action = { type: "bash", args: { command: "git status" } };
const decision = await gate.check(action);
if (decision.outcome === "allow") await gate.record(action, { costUsd: 0.01 });

import { Gate } from "bareguard";
const gate = new Gate({
  audit: { path: null },
  rwx: { agent: "fixer", agents: { fixer: "rwx" }, tools: { read: "r" } },
  humanChannel: async () => ({ decision: "deny" }),
});
await gate.init();
await gate.add({ deploy: "x" }); // new key, mid-run — tighten-only from here
const decision = await gate.check({ type: "deploy", args: {} });
decision.outcome; // "allow"

const gate = new Gate({ rubric: { spec, sha256: rubricSha(spec), advanceOn: ["done"] } });
const r = await gate.checkStep("resume", text);            // r.verdict, r.gaps, r.outputSha
await gate.check({ type: "done", checkpoint: "resume", outputSha: r.outputSha });

import { Gate } from "bareguard";
const gate = new Gate({
  audit: { path: null },
  tools: { allowlist: ["read"] },
  humanChannel: async () => ({ decision: "deny" }),
});
await gate.init();
await gate.check({ type: "read", args: {} });
const lines = await gate.readAudit();
lines.length > 0; // true

import { Gate } from "bareguard";
const gate = new Gate({
  audit: { path: null },
  rwx: { agent: "fixer", agents: { fixer: "rwx" }, tools: { read: "r", write: "w" } },
  humanChannel: async () => ({ decision: "deny" }),
});
await gate.init();
gate.rwxTools(); // { read: "r", write: "w" } — a decoupled copy

import { numbersInQuote } from "bareguard";
numbersInQuote("delivers 8x faster", "delivers 8x faster").ok;   // true
numbersInQuote("delivers in 4 hours", "delivers in 2 weeks");    // { ok: false, missing: ["4"] }

import { redact } from "bareguard";
redact({ apiKey: "sk-live-abcdef0123456789" });
// => { apiKey: "[REDACTED:key=apiKey]" }

import { renderGaps } from "bareguard";
renderGaps([{ key: "resume:words-cap", check: "maxWords", measured: 633, limit: 600, direction: "at-most" }]);
// '["resume:words-cap","maxWords",null,null,633,600,"at-most",null,null]'

import { routeAnnotation } from "bareguard";
routeAnnotation(true, false);            // "annotate-floor-ask" — irreversible + broke
routeAnnotation(true, true, "relaxed"); // "log" — reversible + broke, no human
